{
  "name": "opencode-gemini-subagent",
  "version": "0.1.27",
  "description": "Delegate work to Gemini as an opencode subagent — built-in web search, background tasks, preset automation.",
  "type": "module",
  "main": "dist/plugin.js",
  "bin": {
    "ogs": "dist/cli.js"
  },
  "files": [
    "dist",
    "agents"
  ],
  "scripts": {
    "build": "tsc",
    "prepublishOnly": "tsc"
  },
  "keywords": [
    "opencode",
    "plugin",
    "gemini",
    "subagent",
    "ai",
    "llm"
  ],
  "author": "HyeokjaeLee",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/HyeokjaeLee/opencode-gemini-subagent.git"
  },
  "dependencies": {
    "yaml": "^2.7.1"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.0.0"
  },
  "peerDependenciesMeta": {
    "@opencode-ai/plugin": {
      "optional": true
    }
  },
  "engines": {
    "bun": ">=1.0.0"
  },
  "devDependencies": {
    "@types/bun": "^1.3.13",
    "typescript": "^6.0.3"
  },
  "bugs": {
    "url": "https://github.com/HyeokjaeLee/opencode-gemini-subagent/issues"
  },
  "homepage": "https://github.com/HyeokjaeLee/opencode-gemini-subagent#readme",
  "types": "./dist/plugin.d.ts"
}
